class Runner:
    """A configured test runner: how it is invoked (the interpreter is prepended) and how its result set is read."""
    name: str
    argv: tuple[str, ...]          # after the interpreter; `{out}` is the result-set path, targets follow
    adapter: Callable[[pathlib.Path], ResultSet]


_UNITTEST_RUNNER = r'''
import importlib, json, os, sys, threading, traceback, unittest
out, targets = sys.argv[1], sys.argv[2:]
measure = "--measure" in targets
targets = [t for t in targets if t != "--measure"]
cases, errors = [], []
loader = unittest.TestLoader()
suite = unittest.TestSuite()
ROOT = os.getcwd() + os.sep
current = [None]                 # the case running now: what the tracer and the audit hook attribute to
lines, accessed, arcs = {}, {}, {}
partial = [False]                # set when a case replaced the tracer: the measurement is PARTIAL, never silently FULL

def inside(filename):
    return filename.startswith(ROOT) and "__pycache__" not in filename

def local(frame, event, arg):
    if event == "line" and current[0] is not None:
        rel_path = frame.f_code.co_filename[len(ROOT):].replace(os.sep, "/")
        lines.setdefault(current[0], {}).setdefault(rel_path, set()).add(frame.f_lineno)
        last = _last.get(id(frame))
        if last is not None and last != frame.f_lineno:
            arcs.setdefault(current[0], {}).setdefault(rel_path, set()).add((last, frame.f_lineno))
        _last[id(frame)] = frame.f_lineno
    elif event == "return":
        _last.pop(id(frame), None)
    return local

_last = {}

def tracer(frame, event, arg):
    return local if event == "call" and inside(frame.f_code.co_filename) else None

def audit(event, args):
    if event == "open" and current[0] is not None and args and isinstance(args[0], (str, bytes, os.PathLike)):
        path = os.path.abspath(os.fsdecode(args[0]))
        if inside(path):
            accessed.setdefault(current[0], set()).add(path[len(ROOT):].replace(os.sep, "/"))

if measure:
    sys.addaudithook(audit)
    threading.settrace(tracer)
    sys.settrace(tracer)

def rel(path):
    try:
        return os.path.relpath(path, os.getcwd()).replace(os.sep, "/")
    except ValueError:
        return path.replace(os.sep, "/")

def cause(exc):
    if isinstance(exc, ModuleNotFoundError) and exc.name:
        return {"kind": "IMPORT", "module": exc.name}
    if isinstance(exc, ImportError) and getattr(exc, "name", None):
        return {"kind": "IMPORT", "module": exc.name}
    if isinstance(exc, SyntaxError):
        return {"kind": "SYNTAX", "module": None}
    return {"kind": "OTHER", "module": None}

def files(target):  # a directory target is every test*.py under it, in a fixed order; a file target is itself
    if not os.path.isdir(target):
        yield target
        return
    for base, dirs, names in os.walk(target):
        dirs.sort()
        yield from (os.path.join(base, n) for n in sorted(names) if n.startswith("test") and n.endswith(".py"))

for t in targets:
    target, _, sel = t.partition("::")
    for path in files(target):
        mod = os.path.splitext(rel(path))[0].replace("/", ".")
        try:
            module = importlib.import_module(mod)
        except BaseException as exc:  # a collection failure is reported with its own typed cause; it is not a test error
            errors.append({"path": rel(path), **cause(exc), "detail": "".join(traceback.format_exception_only(exc)).strip()[:500]})
            continue
        suite.addTests(loader.loadTestsFromName(sel, module) if sel else loader.loadTestsFromModule(module))

class Result(unittest.TestResult):
    def __init__(self):
        super().__init__()
        self.seen = {}
    def _path(self, test):
        m = sys.modules.get(type(test).__module__)
        f = getattr(m, "__file__", None)
        return rel(f) if f else type(test).__module__.replace(".", "/") + ".py"
    def _mark(self, test, outcome):
        self.seen[test.id()] = {"id": test.id(), "path": self._path(test), "outcome": outcome}
    def startTest(self, test):
        super().startTest(test)
        self._mark(test, "passed")
        current[0] = test.id()
    def stopTest(self, test):
        super().stopTest(test)
        if measure and sys.gettrace() is not tracer:
            partial[0] = True  # the case replaced the tracer: what ran meanwhile was not observed
            sys.settrace(tracer)
        current[0] = None
    def addError(self, test, err):
        super().addError(test, err)
        self._mark(test, "error")
    def addFailure(self, test, err):
        super().addFailure(test, err)
        self._mark(test, "failed")
    def addSkip(self, test, reason):
        super().addSkip(test, reason)
        self._mark(test, "skipped")
    def addExpectedFailure(self, test, err):
        super().addExpectedFailure(test, err)
        self._mark(test, "passed")
    def addUnexpectedSuccess(self, test):
        super().addUnexpectedSuccess(test)
        self._mark(test, "failed")

result = Result()
suite.run(result)
if measure:
    sys.settrace(None)
    threading.settrace(None)
cases = list(result.seen.values())
level = ("PARTIAL" if partial[0] else "FULL") if measure else "UNAVAILABLE"
capabilities = {"line-coverage": level, "artefact-access": level, "branch-coverage": level}
with open(out, "w", encoding="utf-8") as f:
    json.dump({"cases": cases, "collection_errors": errors, "capabilities": capabilities,
               "lines": {c: {p: sorted(v) for p, v in m.items()} for c, m in lines.items()},
               "accessed": {c: sorted(v) for c, v in accessed.items()},
               "arcs": {c: {p: sorted(v) for p, v in m.items()} for c, m in arcs.items()}}, f)
sys.exit(0 if result.wasSuccessful() else 1)
'''


def _read_unittest(path: pathlib.Path) -> ResultSet:
    d = json.loads(path.read_text(encoding="utf-8"))
    return ResultSet(tuple(Case(c["id"], c["path"], c["outcome"]) for c in d["cases"]),
                     tuple(CollectionError(e["path"], e["kind"], e.get("module"), e.get("detail", ""))
                           for e in d["collection_errors"]),
                     MappingProxyType({k: Enforcement(v) for k, v in d.get("capabilities", {}).items()}),
                     MappingProxyType({c: MappingProxyType({p: frozenset(v) for p, v in m.items()})
                                       for c, m in d.get("lines", {}).items()}),
                     MappingProxyType({c: frozenset(v) for c, v in d.get("accessed", {}).items()}),
                     MappingProxyType({c: MappingProxyType({p: frozenset(map(tuple, v)) for p, v in m.items()})
                                       for c, m in d.get("arcs", {}).items()}))


_IMPORT_ERROR = re.compile(r"(?:ModuleNotFoundError|ImportError): (?:No module named|cannot import name .+? from) '([^']+)'")


def _read_junit(path: pathlib.Path) -> ResultSet:
    """pytest's junit result set (junit_family=xunit1, which the runner's argv fixes: every testcase carries `file`).
    A `collection failure` error is typed by its traceback text: a missing module is IMPORT with the module the
    runner named; a syntax error is SYNTAX; anything else is OTHER."""
    root = ElementTree.parse(path).getroot()
    cases, errors = [], []
    for tc in root.iter("testcase"):
        file = tc.get("file", "").replace(os.sep, "/")
        name = tc.get("name", "")
        error = tc.find("error")
        if error is not None and "collection failure" in error.get("message", ""):
            body = ElementTree.tostring(error, encoding="unicode", method="text")
            m = _IMPORT_ERROR.search(body)
            if m:
                errors.append(CollectionError(file, IMPORT, m.group(1), body[-500:]))
            elif "SyntaxError" in body or "IndentationError" in body:
                errors.append(CollectionError(file, SYNTAX, None, body[-500:]))
            else:
                errors.append(CollectionError(file, OTHER, None, body[-500:]))
            continue
        outcome = ("error" if error is not None else "failed" if tc.find("failure") is not None
                   else "skipped" if tc.find("skipped") is not None else "passed")
        cases.append(Case(f"{file}::{tc.get('classname', '')}::{name}", file, outcome))
    return ResultSet(tuple(cases), tuple(errors))


# -B on the command line (the environment's PYTHONDONTWRITEBYTECODE never reaches an -E interpreter): a runner writes
# no bytecode into the checkout it runs in (P7-FINDING-001 correction, defence in depth)
UNITTEST = Runner("unittest", ("-E", "-s", "-B", "-c", _UNITTEST_RUNNER, "{out}"), _read_unittest)
PYTEST = Runner("pytest", ("-B", "-m", "pytest", "-q", "-p", "no:cacheprovider", "-o", "junit_family=xunit1",
                           "--junitxml", "{out}"), _read_junit)


def _scrubbed_env(extra: Mapping[str, str] | None = None) -> dict:
    keep = ("PATH", "SYSTEMROOT", "SystemRoot", "WINDIR", "TEMP", "TMP", "TMPDIR", "HOME", "USERPROFILE", "LANG")
    return {**{k: os.environ[k] for k in keep if k in os.environ}, "PYTHONDONTWRITEBYTECODE": "1",
            "PYTHONHASHSEED": "0", "PYTHONIOENCODING": "utf-8", **(extra or {})}


def execute(runner: Runner, candidate: str | os.PathLike, tests: DeveloperTests, deps: Dependencies, *,
            interpreter: str = sys.executable, targets: Sequence[str] | None = None, timeout_s: float = _TIMEOUT_S,
            env: Mapping[str, str] | None = None, on_range: Callable[[ProcessRange], None] | None = None,
            ) -> tuple[RunnerReport, TestExecution]:
    """Run `runner` at the candidate over `targets` (the story's tests by default) inside an owned process range, read
    what it reported, and classify. The candidate is the only tree this function knows; there is no parent here."""
    root = pathlib.Path(candidate)
    with tempfile.TemporaryDirectory(prefix="aisef2-tests-") as work:
        out = os.path.join(work, "result-set.json" if runner.name == "unittest" else "result-set.xml")
        argv = [interpreter, *(a.replace("{out}", out) for a in runner.argv), *(targets or tests.paths)]
        run = ProcessRange(f"tests {tests.story_id}", argv, cwd=str(root), env=_scrubbed_env(env),
                           output=subprocess.PIPE, grace_s=_GRACE_S, wait_s=_WAIT_S)
        try:
            run.start()
        except (RangeError, OSError) as e:
            report = RunnerReport(False, None, False, False, None, f"{type(e).__name__}: {e}")
            return report, classify(report, tests, deps)
        if on_range is not None:
            on_range(run)
        chunks: list[str] = []
        pump = threading.Thread(target=_pump, args=(run, chunks), daemon=True)
        pump.start()
        try:
            code = run.wait(timeout_s)
            timed_out = code is None
        finally:
            run.release()  # on the controller's own deadline this is the ladder, in the ledger; else a no-op wait

"""Core LedgerLock implementation: append-only, tamper-evident key/value ledger.

This module is pure standard library (see docs/requirements.md §10 and §12).
"""

from __future__ import annotations

import hashlib
import json
import os
import tempfile
import unicodedata
from pathlib import Path
from typing import Any, Iterable

#: The literal predecessor of the first record's hash. Constant per §3.2.
GENESIS = "GENESIS"


def _normalize_key(key: str) -> str:
    return unicodedata.normalize("NFC", key)


def _canonical_line(obj: dict[str, Any]) -> bytes:
    """Canonical byte serialization of a JSONL record.

    Deterministic: keys sorted, compact separators, no ASCII escaping.
    """
    return json.dumps(
        obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def _hash_line(prev_hash: str, canonical: bytes) -> str:
    return hashlib.sha256(prev_hash.encode("utf-8") + b"|" + canonical).hexdigest()


class ConflictError(Exception):
    """Raised when a mutation conflicts with the last committed mutation for a key."""


class Ledger:
    """Append-only, hash-chained, idempotent key/value ledger."""

    GENESIS = GENESIS

    def __init__(self, path: str | os.PathLike[str]) -> None:
        self.path = Path(path)
        # key -> (rid, op, value, ts, hash) of the last committed mutation.
        self._last: dict[str, tuple[str, str, Any, int, str]] = {}
        self._tail_hash: str = self.GENESIS
        self._reload()

    def _reload(self) -> None:
        self._last = {}
        self._tail_hash = self.GENESIS
        if not self.path.exists():
            return
        with open(self.path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.rstrip("\n")
                if line == "":
                    continue
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError:
                    break  # stop at a malformed (e.g. truncated) tail line
                if not isinstance(obj, dict):
                    break
                key = obj["key"]
                self._last[key] = (
                    obj["id"],
                    obj["op"],
                    obj.get("value"),
                    obj["ts"],
                    obj["hash"],
                )
                self._tail_hash = obj["hash"]

    def _validate(self, op: str, key: str, value: Any, rid: Any, ts: Any) -> str:
        if op not in ("put", "delete"):
            raise ValueError("op must be 'put' or 'delete'")
        if not isinstance(rid, str) or rid == "":
            raise ValueError("rid must be a non-empty string")
        if isinstance(ts, bool) or not isinstance(ts, int):
            raise ValueError("ts must be an int")
        return _normalize_key(key)

    def _make_line(self, op: str, key: str, value: Any, rid: str, ts: int) -> dict[str, Any]:
        obj: dict[str, Any] = {"op": op, "key": key, "ts": ts, "id": rid}
        if op == "put":
            obj["value"] = value
        return obj

    def _chain_hash(self, prev_hash: str, line: dict[str, Any]) -> str:
        canon = dict(line)
        canon["hash"] = ""
        canon["prev_hash"] = ""
        return _hash_line(prev_hash, _canonical_line(canon))

    def _write_line(self, line: dict[str, Any]) -> None:
        data = _canonical_line(line) + b"\n"
        with open(self.path, "ab") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())

    def append(
        self,
        op: str,
        key: str,
        value: Any = None,
        rid: str | None = None,
        ts: int | None = None,
    ) -> str:
        """Append a single mutation. Returns the hex hash of the committed line.

        Idempotent: replaying the same rid returns the same hash and appends nothing.
        Raises ConflictError if the key's last committed mutation used a different rid.
        """
        key = self._validate(op, key, value, rid, ts)
        prev = self._last.get(key)
        if prev is not None:
            if prev[0] == rid:
                return prev[4]
            raise ConflictError(
                f"key {key!r} was last mutated by rid {prev[0]!r}, not {rid!r}"
            )
        line = self._make_line(op, key, value, rid, ts)
        h = self._chain_hash(self._tail_hash, line)
        line["prev_hash"] = self._tail_hash
        line["hash"] = h
        self._write_line(line)
        self._tail_hash = h
        self._last[key] = (rid, op, value, ts, h)
        return h

    def verify(self) -> dict[str, Any]:
        """Independently recompute the hash chain from disk end-to-end.

        Returns {"ok": bool, "first_bad_index": int | None}.
        """
        if not self.path.exists():
            return {"ok": True, "first_bad_index": None}
        prev_hash = self.GENESIS
        with open(self.path, "r", encoding="utf-8") as f:
            for i, line in enumerate(f):
                line = line.rstrip("\n")
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError:
                    return {"ok": False, "first_bad_index": i}
                if not isinstance(obj, dict):
                    return {"ok": False, "first_bad_index": i}
                if "hash" not in obj or "prev_hash" not in obj:
                    return {"ok": False, "first_bad_index": i}
                stored_hash = obj["hash"]
                stored_prev = obj["prev_hash"]
                canon = dict(obj)
                canon["hash"] = ""
                canon["prev_hash"] = ""
                recomputed = _hash_line(stored_prev, _canonical_line(canon))
                if recomputed != stored_hash:
                    return {"ok": False, "first_bad_index": i}
                if stored_prev != prev_hash:
                    return {"ok": False, "first_bad_index": i}
                prev_hash = stored_hash
        return {"ok": True, "first_bad_index": None}

    def snapshot(self) -> dict[str, Any]:
        """Return the materialized state, keyed by NFC-normalized key, sorted.

        Deterministic: same chain content yields the same dict (and serialized bytes).
        """
        result: dict[str, Any] = {}
        for key in sorted(self._last):
            rid, op, value, ts, h = self._last[key]
            if op == "put":
                result[key] = value
        return result

    def apply_batch(self, ops: Iterable[tuple]) -> None:
        """Atomically apply an iterable of (op, key, value, rid, ts) tuples.

        All-or-nothing: writes to a sibling temp file, fsyncs, then renames.
        """
        working = dict(self._last)
        tail_hash = self._tail_hash
        new_lines: list[dict[str, Any]] = []
        for op, key, value, rid, ts in ops:
            key = self._validate(op, key, value, rid, ts)
            prev = working.get(key)
            if prev is not None:
                if prev[0] == rid:
                    continue
                raise ConflictError(
                    f"key {key!r} was last mutated by rid {prev[0]!r}, not {rid!r}"
                )
            line = self._make_line(op, key, value, rid, ts)
            h = self._chain_hash(tail_hash, line)
            line["prev_hash"] = tail_hash
            line["hash"] = h
            tail_hash = h
            working[key] = (rid, op, value, ts, h)
            new_lines.append(line)

        if not new_lines:
            return

        self._atomic_append(new_lines)
        self._last = working
        self._tail_hash = tail_hash

    def _atomic_append(self, new_lines: list[dict[str, Any]]) -> None:
        parent = str(self.path.parent) or "."
        fd, tmp = tempfile.mkstemp(
            dir=parent, prefix=self.path.name + ".", suffix=".tmp"
        )
        try:
            with os.fdopen(fd, "wb") as f:
                if self.path.exists():
                    with open(self.path, "rb") as src:
                        while True:
                            chunk = src.read(65536)
                            if not chunk:
                                break
                            f.write(chunk)
                for line in new_lines:
                    f.write(_canonical_line(line) + b"\n")
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, self.path)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise


def append(
    path: str | os.PathLike[str],
    op: str,
    key: str,
    value: Any = None,
    rid: str | None = None,
    ts: int | None = None,
) -> str:
    """Append a single mutation to the ledger at ``path`` and return its hex hash.

    Module-level convenience wrapper around :meth:`Ledger.append`. The same
    idempotency and conflict rules apply (see docs/requirements.md §4).
    """
    return Ledger(path).append(op, key, value, rid, ts)


def snapshot(path: str | os.PathLike[str]) -> dict[str, Any]:
    """Return the materialized state of the ledger at ``path``.

    Module-level convenience wrapper around :meth:`Ledger.snapshot`. Returns a
    deterministic dict mapping each NFC-normalized key to its latest committed
    ``put`` value, sorted by key, with tombstoned keys omitted (see
    docs/requirements.md §6).
    """
    return Ledger(path).snapshot()


def verify(path: str | os.PathLike[str]) -> dict[str, Any]:
    """Independently verify the hash chain of the ledger at ``path``.

    Module-level convenience wrapper around :meth:`Ledger.verify`. Reads and
    recomputes the chain from disk only, never from in-memory state
    (docs/requirements.md §3.4).
    """
    return Ledger(path).verify()


def apply_batch(path: str | os.PathLike[str], ops: Iterable[tuple]) -> None:
    """Atomically apply a batch of mutations to the ledger at ``path``.

    Module-level convenience wrapper around :meth:`Ledger.apply_batch`. The
    same all-or-nothing, idempotency, and conflict rules apply
    (docs/requirements.md §4 and §5).
    """
    Ledger(path).apply_batch(ops)

